#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    map<string, long long> net;
    char sym[16];
    for (int i = 0; i < n; i++) {
        long long q;
        scanf("%15s %lld", sym, &q);
        net[string(sym)] += q;
    }
    string out;
    for (const auto &kv : net) {
        out += kv.first;
        out += ' ';
        out += to_string(kv.second);
        out += '\n';
    }
    fputs(out.c_str(), stdout);
    return 0;
}
